sp_widget.client_script:
function($scope) {
    var chartData = $scope.data.series;

    window.addEventListener('load', function () {
        setTimeout(function () {
            if (chartData && Array.isArray(chartData)) {
                var anos = [];
                var despesas = [];
                var receitas = [];
                var comprometimento = [];

                for (var i = 0; i < chartData.length; i++) {
                    var ano = chartData[i].ano;
                    var despesa = chartData[i].despesa;
                    var receita = chartData[i].receita;
                    var perc = (despesa / receita) * 100;

                    anos.push(ano);
                    despesas.push(despesa / 1000000);
                    receitas.push(receita / 1000000);
                    comprometimento.push(parseFloat(perc.toFixed(2)));
                }

                var limiteAlerta = new Array(chartData.length).fill(54);

                var ctx = document.getElementById('graficoComposto').getContext('2d');

                new Chart(ctx, {
                    type: 'bar',
                    data: {
                        labels: anos,
                        datasets: [
                            {
                                type: 'bar',
                                label: 'Despesa Líquida com Pessoal',
                                data: despesas,
                                backgroundColor: '#66c2ff'
                            },
                            {
                                type: 'bar',
                                label: 'Receita Corrente Líquida',
                                data: receitas,
                                backgroundColor: '#003f87'
                            },
                            {
                                type: 'line',
                                label: 'Comprometimento RCL com Pessoal (%)',
                                data: comprometimento,
                                borderColor: '#00c8aa',
                                backgroundColor: '#00c8aa20',
                                borderWidth: 2,
                                tension: 0.3,
                                yAxisID: 'yPercent'
                            },
                            {
                                type: 'line',
                                label: 'Limite de Alerta',
                                data: limiteAlerta,
                                borderColor: '#ff3b3b',
                                borderDash: [5, 5],
                                borderWidth: 2,
                                pointRadius: 0,
                                fill: false,
                                yAxisID: 'yPercent'
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            tooltip: {
                                callbacks: {
                                    label: function (context) {
                                        if (context.dataset.label.includes('%')) {
                                            return `${context.dataset.label}: ${context.parsed.y.toFixed(2)}%`;
                                        } else {
                                            return `${context.dataset.label}: ${context.parsed.y.toLocaleString('pt-BR')} mi`;
                                        }
                                    }
                                }
                            },
                            legend: {
                                position: 'top'
                            }
                        },
                        scales: {
                            y: {
                                beginAtZero: true,
                                title: {
                                    display: true,
                                    text: 'Milhões (R$)'
                                },
                                ticks: {
                                    callback: function (value) {
                                        return value.toLocaleString('pt-BR') + ' mi';
                                    }
                                }
                            },
                            yPercent: {
                                position: 'right',
                                beginAtZero: true,
                                min: 0,
                                max: 70,
                                title: {
                                    display: true,
                                    text: '% Comprometimento'
                                },
                                ticks: {
                                    callback: function (value) {
                                        return value + '%';
                                    }
                                },
                                grid: {
                                    drawOnChartArea: false
                                }
                            },
                            x: {
                                title: {
                                    display: true,
                                    text: 'Ano'
                                }
                            }
                        }
                    }
                });
            } else {
                console.warn("Sem dados para o gráfico.");
            }
        }, 500);
    });






}

sp_widget.css:
.chart-wrapper {
  width: 100%;
  height: 100%;
  padding: 20px;
  background-color: #fff;
  border-radius: 12px;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
  margin: 40px 0;
  box-sizing: border-box;

  display: flex;
  flex-direction: column;
}

.chart-title {
  text-align: center;
  font-weight: 600;
  margin-bottom: 16px;
}

.chart-container {
  flex: 1;
  position: relative;
  width: 100%;
  height: 500px;
}

.chart-container canvas {
  width: 100% !important;
  height: 100% !important;
  display: block;
}

/* Responsividade */
@media (max-width: 1024px) {
  .chart-container {
    height: 400px;
  }
}

@media (max-width: 768px) {
  .chart-container {
    height: 350px;
  }
}

@media (max-width: 480px) {
  .chart-container {
    height: 300px;
  }
}

sp_widget.script:
(function() {
    var dados = [];
    var gr = new GlideRecord('x_sded9_portal_t_0_u_despesa_pessoal');
    gr.orderBy('u_ano');
    gr.query();

    while (gr.next()) {
        dados.push({
            ano: gr.getValue('u_ano'),
            despesa: parseFloat(gr.getValue('u_despesa_liquida_pedidos')) || 0,
            receita: parseFloat(gr.getValue('u_receita_corrente_liquida')) || 0
        });
    }

    data.series = dados;
})();
